package mz.gov.mogovolas.expedientes.service; import jakarta.servlet.http.HttpServletRequest; import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import org.springframework.stereotype.Service; import java.time.*;
@Service public class AuditoriaService {final AuditoriaRepository repo; final UtilizadorRepository users; public AuditoriaService(AuditoriaRepository r,UtilizadorRepository u){repo=r;users=u;} public void registar(String user,String acao,String ent,Long id,HttpServletRequest req,String det){Auditoria a=new Auditoria();users.findByUsername(user).ifPresent(a::setUtilizador);a.setAcao(acao);a.setEntidade(ent);a.setEntidadeId(id);a.setDataHora(LocalDateTime.now());a.setEnderecoIp(req==null?null:req.getRemoteAddr());a.setDetalhes(det);repo.save(a);}}
